	int g_failures = 0;
	int g_checks = 0;

	void Check(bool a_ok, const std::string& a_message)
	{
		++g_checks;
		if (!a_ok) {
			++g_failures;
			if (g_failures <= 40) std::cerr << "runeforge_workstation_policy: " << a_message << "\n";
		}
	}

	std::vector<std::string> Split(const std::string& a_text, char a_separator)
	{
		std::vector<std::string> out;
		std::string current;
		std::istringstream stream(a_text);
		while (std::getline(stream, current, a_separator)) out.push_back(current);
		return out;
	}

	bool ParseCause(const std::string& a_text, Cause& a_cause)
	{
		static const std::map<std::string, Cause> causes{
			{ "HIT", Cause::kHit }, { "COMBAT", Cause::kCombat }, { "DEATH", Cause::kDeath }, { "CELL", Cause::kCell },
			{ "FORCED", Cause::kForced }, { "F10", Cause::kF10 }, { "EMERGENCY", Cause::kEmergency }, { "RACE", Cause::kRace },
			{ "PRELOAD", Cause::kPreload }, { "STANCE_FAILED", Cause::kStanceFailed }, { "STANCE_LOST", Cause::kStanceLost },
			{ "LEASE_FAILED", Cause::kLeaseFailed } };
		const auto it = causes.find(a_text);
		if (it == causes.end()) return false;
		a_cause = it->second;
		return true;
	}

	bool ParseEvent(const std::vector<std::string>& a_tokens, Event& a_event)
	{
		static const std::map<std::string, EventKind> kinds{
			{ "OPEN", EventKind::kOpen }, { "ACK_READY", EventKind::kAckReady }, { "ACK_CLEARED", EventKind::kAckCleared },
			{ "LEASE", EventKind::kLease }, { "SEATED", EventKind::kSeated }, { "ACK_ITEM", EventKind::kAckItem },
			{ "ACK_RUNES", EventKind::kAckRunes }, { "TICK", EventKind::kTick }, { "FOCUS_ITEM", EventKind::kFocusItem },
			{ "FOCUS_FORMULA", EventKind::kFocusFormula }, { "ACCEPT", EventKind::kAccept }, { "HOLD_BEGIN", EventKind::kHoldBegin },
			{ "HOLD_END", EventKind::kHoldEnd }, { "BACK", EventKind::kBack }, { "OPS", EventKind::kOps },
			{ "COMMIT_RESULT", EventKind::kCommitResult }, { "INTERRUPT", EventKind::kInterrupt }, { "POSTLOAD", EventKind::kPostLoad },
			{ "SEED_TOKEN", EventKind::kSeedToken }, { "ACQ", EventKind::kAcq }, { "LEASE_VERIFIED", EventKind::kLeaseVerified },
			{ "RESTORED", EventKind::kRestored } };
		static const std::map<std::string, WS::StatePolicy::AcqPhase> phases{
			{ "PLACE", WS::StatePolicy::AcqPhase::kPlace }, { "SETTLE", WS::StatePolicy::AcqPhase::kSettle },
			{ "ACTIVATE", WS::StatePolicy::AcqPhase::kActivate }, { "VERIFY_SEAT", WS::StatePolicy::AcqPhase::kVerifySeat } };
		if (a_tokens.size() < 2) return false;
		const auto it = kinds.find(a_tokens[1]);
		if (it == kinds.end()) return false;
		a_event = Event{};
		a_event.kind = it->second;
		if (a_event.kind == EventKind::kInterrupt) return a_tokens.size() > 2 && ParseCause(a_tokens[2], a_event.cause);
		if (a_event.kind == EventKind::kAcq) {
			const auto phase = a_tokens.size() > 2 ? phases.find(a_tokens[2]) : phases.end();
			if (phase == phases.end()) return false;
			a_event.a = static_cast<std::int64_t>(phase->second);
			return true;
		}
		if (a_tokens.size() > 2) a_event.a = std::stoll(a_tokens[2]);
		if (a_tokens.size() > 3) a_event.b = std::stoll(a_tokens[3]);
		if (a_tokens.size() > 4) a_event.c = std::stoll(a_tokens[4]);
		return true;
	}

	void RunVectors(const std::string& a_path)
	{
		std::ifstream in(a_path);
		Check(in.good(), "cannot open vectors " + a_path);
		if (!in.good()) return;
		std::string line;
		std::string vectorId;
		WS::StatePolicy::Session session{};
		Event pending{};
		bool havePending = false;
		std::string pendingText;
		int vectors = 0;
		int steps = 0;
		int layouts = 0;
		while (std::getline(in, line)) {
			if (line.empty() || line[0] == '#') continue;
			const auto tokens = Split(line, ' ');
			if (tokens[0] == "P") {
				const WS::StatePolicy::Timing timing{};
				const WS::InputPolicy::Timing input{};
				std::map<std::string, long long> values;
				for (std::size_t i = 1; i < tokens.size(); ++i) {
					const auto kv = Split(tokens[i], '=');
					if (kv.size() == 2) values[kv[0]] = std::stoll(kv[1]);
				}
				Check(values["focusSettleMs"] == timing.focusSettleMs && values["acquisitionTimeoutMs"] == timing.acquisitionTimeoutMs &&
						values["runeAckTimeoutMs"] == timing.runeAckTimeoutMs && values["runeAckTimeoutMs"] == WS::StagePolicy::kFlightTimeoutMs &&
						values["holdConfirmMs"] == timing.holdConfirmMs && values["firstStrikeMs"] == timing.firstStrikeMs &&
						values["strikeIntervalMs"] == timing.strikeIntervalMs && values["bindAfterLastStrikeMs"] == timing.bindAfterLastStrikeMs &&
						values["revealAfterBindMs"] == timing.revealAfterBindMs && values["resultHoldMs"] == timing.resultHoldMs &&
						values["exitWatchdogMs"] == timing.exitWatchdogMs && values["tokenModulus"] == timing.tokenModulus &&
						values["maxRunes"] == timing.maxRunes,
					"state timing constants differ from workstation-performance.v3.json");
				Check(std::lround(input.repeatDelaySeconds * 1000.0f) == values["repeatDelayMs"] &&
						std::lround(input.repeatIntervalSeconds * 1000.0f) == values["repeatIntervalMs"] &&
						std::lround(input.emergencyHoldSeconds * 1000.0f) == values["emergencyHoldMs"],
					"input timing constants differ from workstation-performance.v3.json");
			} else if (tokens[0] == "V") {
				vectorId = tokens.size() > 1 ? tokens[1] : "?";
				session = WS::StatePolicy::Session{};
				havePending = false;
				++vectors;
			} else if (tokens[0] == "E") {
				havePending = ParseEvent(tokens, pending);
				pendingText = line;
				Check(havePending, vectorId + ": unparsable event '" + line + "'");
			} else if (tokens[0] == "R" && havePending) {
				WS::StatePolicy::Effects fx;
				WS::StatePolicy::Step(session, pending, fx);
				std::string got;
				for (const auto& effect : fx) {
					if (!got.empty()) got += ";";
					got += WS::StatePolicy::Format(effect);
				}
				if (got.empty()) got = "-";
				const std::string want = tokens.size() > 3 ? tokens[3] : "-";
				const std::string gotState(WS::StatePolicy::Name(session.state));
				Check(gotState == tokens[1] && std::to_string(session.token) == tokens[2] && got == want,
					vectorId + " step " + std::to_string(steps) + " '" + pendingText + "': want " + tokens[1] + " " + tokens[2] + " " + want +
						" got " + gotState + " " + std::to_string(session.token) + " " + got);
				havePending = false;
				++steps;
			} else if (tokens[0] == "S") {
				const auto n = static_cast<std::uint32_t>(std::stoul(tokens[1]));
				const auto slots = Split(tokens[2], ';');
				Check(slots.size() == n, "rune slot count for n=" + tokens[1]);
				for (std::uint32_t i = 0; i < slots.size(); ++i) {
					const auto xyz = Split(slots[i], ',');
					const auto slot = WS::LayoutPolicy::Slot(i, n);
					Check(std::fabs(slot.x - std::stod(xyz[0])) < 1e-6 && std::fabs(slot.y - std::stod(xyz[1])) < 1e-6 && std::fabs(slot.z - std::stod(xyz[2])) < 1e-6,
						"rune slot " + std::to_string(i) + " of " + tokens[1]);
				}
				++layouts;
			} else if (tokens[0] == "I") {
				const auto b = Split(tokens[3], ',');
				const WS::LayoutPolicy::Bounds bounds{ std::stoi(b[0]), std::stoi(b[1]), std::stoi(b[2]), std::stoi(b[3]), std::stoi(b[4]), std::stoi(b[5]) };
				const auto pose = WS::LayoutPolicy::Pose(WS::LayoutPolicy::ClassFromName(tokens[2]), bounds);
				const std::string poseClass(WS::LayoutPolicy::Name(pose.itemClass));
				bool ok = poseClass == tokens[4];
				if (ok && poseClass != "NEUTRAL") {
					ok = std::fabs(pose.x - std::stod(tokens[5])) < 1e-6 && std::fabs(pose.y - std::stod(tokens[6])) < 1e-6 &&
						std::fabs(pose.z - std::stod(tokens[7])) < 1e-6 && pose.yawDegrees == std::stoi(tokens[8]) && std::fabs(pose.scale - std::stod(tokens[9])) < 1e-6;
				}
				Check(ok, "item pose " + tokens[1]);
				++layouts;
			} else if (tokens[0] == "F") {
				const WS::ShotPolicy::Frame frame{ { std::stof(tokens[1]), std::stof(tokens[2]), std::stof(tokens[3]) }, std::stof(tokens[4]) };
				const auto world = WS::ShotPolicy::LocalToWorld(frame, { std::stof(tokens[5]), std::stof(tokens[6]), std::stof(tokens[7]) });
				Check(std::fabs(world.x - std::stod(tokens[8])) < 1e-3 && std::fabs(world.y - std::stod(tokens[9])) < 1e-3 &&
						std::fabs(world.z - std::stod(tokens[10])) < 1e-3,
					"slab frame transform " + line);
				++layouts;
			}
		}
		Check(vectors >= 400 && steps >= 10000 && layouts >= 30, "vector file is incomplete");
		std::cout << "runeforge_workstation_vectors: " << vectors << " vectors, " << steps << " steps, " << layouts << " layout checks\n";
	}

	// ---------------------------------------------------------------- R8.7.4.21 (feasr-core/alpha/rc/r87421/I2-workstation)

	// The item cradle vectors of A3 (alpha/rc/r87421/A3-preview findings, toAddWithF2) and the slab-local inverse.
	void CradleChecks()
	{
		using namespace WS::LayoutPolicy;
		Check(CradleContains(23.6, -48.5, 64.0), "cradle: the gear anchor on the slab top is in");
		Check(!CradleContains(72.0, -57.0, 66.3), "cradle: the chisel (R1 EngravingToolRef) is out");
		Check(!CradleContains(-70.0, -48.5, 66.28), "cradle: the rune row is out");
		Check(!CradleContains(23.6, -65.0, 64.0) && !CradleContains(23.6, 30.01, 64.0), "cradle: y outside the footprint is out");
		Check(!CradleContains(23.6, -48.5, 39.0) && CradleContains(23.6, -48.5, 40.0) && CradleContains(23.6, -48.5, 140.0) && !CradleContains(23.6, -48.5, 140.01),
			"cradle: z 40..140");
		Check(CradleContains(-16.0, -48.5, 64.0) && CradleContains(62.0, -48.5, 64.0) && !CradleContains(-16.01, -48.5, 64.0) && !CradleContains(62.01, -48.5, 64.0),
			"cradle: x -16..62");
		const LocalPoint slab{ -170.0, 40.0, 0.0 };
		const auto r7b = WorldToSlab(slab, 0.0, { -146.4, -8.5, 64.0 });
		Check(std::fabs(r7b.x - 23.6) < 1e-9 && std::fabs(r7b.y + 48.5) < 1e-9 && CradleContains(r7b.x, r7b.y, r7b.z), "the R7B ItemPreviewRef (FE06B80F) lies in the cradle");
		for (const double yaw : { 0.0, 0.5235987755982988, 1.5707963267948966, -2.0 }) {
			for (const LocalPoint p : { LocalPoint{ 23.6, -48.5, 64.0 }, LocalPoint{ -70.0, 12.0, 66.0 }, LocalPoint{ 61.0, 29.0, 139.0 } }) {
				const auto w = SlabToWorld({ 100.0, -20.0, 10.0 }, yaw, p);
				const auto back = WorldToSlab({ 100.0, -20.0, 10.0 }, yaw, w);
				Check(std::fabs(back.x - p.x) < 1e-9 && std::fabs(back.y - p.y) < 1e-9 && std::fabs(back.z - p.z) < 1e-9, "WorldToSlab inverts SlabToWorld");
			}
		}
		const auto rotated = SlabToWorld({ 0.0, 0.0, 0.0 }, 1.5707963267948966, { 10.0, 0.0, 0.0 });
		Check(std::fabs(rotated.x) < 1e-9 && std::fabs(rotated.y + 10.0) < 1e-9, "Skyrim heading: +90 turns slab +X to world -Y (stage host PlaceLocal)");
	}

	// A3 G1/G2/G3: what the idle native sweep may touch and how.
	void SweepChecks()
	{
		using namespace WS::SweepPolicy;
		RefFacts pluginDisplay{};  // R7B RunePreview01..06: plugin-placed, Presentation display base, enabled
		pluginDisplay.displayBase = true;
		RefFacts dynamicDisplay = pluginDisplay;
		dynamicDisplay.dynamic = true;
		Check(ForCellScan(pluginDisplay, true) == Action::kDisable, "G2: a plugin-placed display ref is only disabled, never deleted");
		Check(ForCellScan(dynamicDisplay, true) == Action::kDisableAndDelete, "a runtime display clone is disabled and deleted");
		RefFacts retired = pluginDisplay;
		retired.disabled = true;
		Check(ForCellScan(retired, true) == Action::kKeep, "a disabled plugin ref is already retired: untouched");
		RefFacts disabledClone = dynamicDisplay;
		disabledClone.disabled = true;
		Check(ForCellScan(disabledClone, true) == Action::kDisableAndDelete, "a disabled runtime clone is still deleted");
		RefFacts gone = dynamicDisplay;
		gone.deleted = true;
		Check(ForCellScan(gone, true) == Action::kKeep && ForTracked(gone) == Action::kKeep, "a deleted ref is never touched again");
		RefFacts orphan{};  // an item preview clone that escaped every ledger
		orphan.dynamic = true;
		orphan.inventoryBase = true;
		orphan.activationBlocked = true;
		orphan.inCradle = true;
		Check(IsOrphanItemClone(orphan) && ForCellScan(orphan, true) == Action::kDisableAndDelete, "G1: an unledgered item clone in the cradle is removed");
		RefFacts dropped = orphan;  // the player dropped an item onto the slab: dynamic, never activation-blocked
		dropped.activationBlocked = false;
		Check(!IsOrphanItemClone(dropped) && ForCellScan(dropped, true) == Action::kKeep, "a player-dropped item on the slab is never touched");
		RefFacts placedWeapon = orphan;  // a plugin-placed weapon in the cradle
		placedWeapon.dynamic = false;
		Check(!IsOrphanItemClone(placedWeapon) && ForCellScan(placedWeapon, true) == Action::kKeep, "a plugin-placed item is never removed by the orphan rule");
		RefFacts outside = orphan;
		outside.inCradle = false;
		Check(ForCellScan(outside, true) == Action::kKeep, "a blocked clone outside the cradle is not an orphan preview");
		RefFacts statPreview{};  // a non-inventory dynamic static in the cradle
		statPreview.dynamic = true;
		statPreview.activationBlocked = true;
		statPreview.inCradle = true;
		Check(ForCellScan(statPreview, true) == Action::kKeep, "only inventory-item bases qualify as orphan previews");
		for (const auto& f : { pluginDisplay, dynamicDisplay, orphan, disabledClone }) Check(ForCellScan(f, false) == Action::kKeep, "nothing is swept while a session owns the slab");
		RefFacts tracked{};
		tracked.dynamic = true;
		Check(ForTracked(tracked) == Action::kDisableAndDelete, "a tracked runtime ref is deleted");
		tracked.dynamic = false;
		Check(ForTracked(tracked) == Action::kDisable, "a tracked plugin ref is only disabled");
		RefFacts dagger{};  // FE06B80F: R7B ItemPreviewRef, a plugin STAT re-enabled in the cradle by R7C
		dagger.inCradle = true;
		Check(IsCradleIntruder(dagger) && ForCellScan(dagger, true) == Action::kKeep, "G3: placed dressing in the cradle is reported, never touched");
		RefFacts slab = dagger;
		slab.allowListed = true;
		RefFacts retiredDagger = dagger;
		retiredDagger.disabled = true;
		Check(!IsCradleIntruder(slab) && !IsCradleIntruder(retiredDagger) && !IsCradleIntruder(orphan) && !IsCradleIntruder(pluginDisplay),
			"the slab / anchor / host, a disabled fixture, runtime clones and display refs are no intruders");
	}

	// Drives a session to PERFORMING with a_runes runes (seat, lease, ready, row OK, hold, commit accepted).
	WS::StatePolicy::Session ToPerforming(std::int64_t a_runes, const WS::StatePolicy::Timing& a_t)
	{
		using namespace WS::StatePolicy;
		Session s{};
		Effects fx;
		const auto step = [&](Event e) { Step(s, e, fx, a_t); };
		step({ EventKind::kOpen, 1, 0, {} });
		for (const auto phase : { AcqPhase::kSettle, AcqPhase::kActivate, AcqPhase::kVerifySeat }) step({ EventKind::kAcq, static_cast<std::int64_t>(phase), 0, {} });
		step({ EventKind::kSeated, 1, 0, {} });
		step({ EventKind::kLease, 1, 0, {} });
		step({ EventKind::kAckReady, static_cast<std::int64_t>(s.token), 0, {} });
		step({ EventKind::kLeaseVerified, 1, 0, {} });
		step({ EventKind::kAccept, 1, 0, {} });
		step({ EventKind::kFocusFormula, 0, a_runes, {} });
		step({ EventKind::kAccept, 1, 0, {} });
		step({ EventKind::kAckRunes, static_cast<std::int64_t>(s.token), s.runeSeq, {}, 1 });
		step({ EventKind::kHoldBegin, 0, 0, {} });
		step({ EventKind::kTick, a_t.holdConfirmMs, 0, {} });
		step({ EventKind::kCommitResult, 1, 0, {} });
		return s;
	}

	struct BeatLog
	{
		std::vector<std::int64_t> strikes;
		std::int64_t bind{ -1 };
		std::int64_t result{ -1 };
	};

	// Runs a performance in 10 ms ticks. a_landedAfter: ms after each strike the host reports LANDED (< 0: never);
	// a_sealAfter: ms after the BIND the host reports SEAL|DONE (< 0: never); a_ackToken: the token the acks carry (0 = the session's).
	BeatLog RunPerformance(std::int64_t a_runes, const WS::StatePolicy::Timing& a_t, std::int64_t a_landedAfter, std::int64_t a_sealAfter,
		std::int64_t a_limitMs = 30000, std::uint32_t a_ackToken = 0, std::int64_t a_ackIndexOffset = 0)
	{
		using namespace WS::StatePolicy;
		auto s = ToPerforming(a_runes, a_t);
		BeatLog log;
		const auto tok = static_cast<std::int64_t>(a_ackToken ? a_ackToken : s.token);
		std::int64_t now = 0;
		std::vector<std::pair<std::int64_t, Event>> pending;
		while (now <= a_limitMs && s.state == State::kPerforming) {
			for (auto it = pending.begin(); it != pending.end();) {
				if (it->first <= now) {
					Effects none;
					Step(s, it->second, none, a_t);
					it = pending.erase(it);
				} else {
					++it;
				}
			}
			Effects fx;
			Step(s, { EventKind::kTick, 10, 0, {} }, fx, a_t);
			now += 10;
			for (const auto& e : fx) {
				if (e.kind == EffectKind::kBeatStrike) {
					log.strikes.push_back(now);
					if (a_landedAfter >= 0) pending.push_back({ now + a_landedAfter, Event{ EventKind::kAckBeat, tok, e.a + a_ackIndexOffset, {}, 1 } });
				}
				if (e.kind == EffectKind::kBeatBind) {
					log.bind = now;
					if (a_sealAfter >= 0) pending.push_back({ now + a_sealAfter, Event{ EventKind::kAckSeal, tok, 0, {} } });
				}
			}
			if (s.state == State::kResultSuccess) log.result = now;
		}
		return log;
	}

	// R8.7.4.22: the capped wait. A 30 fps Papyrus host (LANDED 3100 ms after each strike, 1600 ms past the schedule; SEAL|DONE 2400 ms
	// after the BIND) is waited for, so every rune plays out; the RC2 700 ms bound (cap off) cut each such rune short; a host later
	// than the cap is never waited for beyond it, and after that lapse the rest of the performance uses 700 ms.
	void TimingV3CapChecks()
	{
		using namespace WS::StatePolicy;
		const auto& t = kPerformanceV3;
		const auto slow30 = RunPerformance(3, t, 3100, 2400);
		Check(slow30.strikes == std::vector<std::int64_t>{ 600, 3710, 6820 } && slow30.bind == 9930 && slow30.result == 12340,
			"30 fps host: each beat waits for the LANDED / SEAL|DONE (strikes 600 / 3710 / 6820, BIND 9930, reveal 12340)");
		Timing rc2 = t;
		rc2.beatAckWaitCapMs = 0;
		const auto cut = RunPerformance(3, rc2, 3100, 2400);
		Check(cut.strikes == std::vector<std::int64_t>{ 600, 2800, 5000 } && cut.bind == 7500 && cut.result == 9100,
			"control (cap off = RC2): the 30 fps host is cut at schedule + 700 (strikes 600 / 2800 / 5000)");
		const auto late = RunPerformance(3, t, 5000, -1);
		Check(late.strikes == std::vector<std::int64_t>{ 600, 4700, 6900 } && late.result > 0,
			"hard cap: a LANDED later than the cap is not waited for beyond schedule + 2600, then the base 700 applies");
		const auto six = RunPerformance(6, t, 3000, 3300);
		Check(six.strikes.size() == 6 && six.strikes[1] == 600 + 3000 + 10 && six.result > 0 && six.result <= 600 + 5 * 1100 + 1800 + 900 + 7 * 2600,
			"30 fps, 6 runes: every gate waits within the cap and the result is reached");
		// the lapse is per performance: a new commit starts with the cap again
		auto s = ToPerforming(2, t);
		s.ackLapsed = true;
		Effects fx;
		Step(s, { EventKind::kAccept, 1, 0, {} }, fx, t);   // skip to the result
		Check(detail::GateWait(s, t) == 700, "a lapsed performance waits the base 700");
		const auto fresh = ToPerforming(2, t);
		Check(!fresh.ackLapsed && detail::GateWait(fresh, t) == 2600, "a new performance waits up to the cap");
	}

	// Timing v3 and the LANDED / SEAL gates: a prompt host keeps the schedule, a slow host shifts it, a silent host never blocks it.
	void TimingV3Checks()
	{
		using namespace WS::StatePolicy;
		const auto& t = kPerformanceV3;
		Check(t.firstStrikeMs == 600 && t.strikeIntervalMs == 1500 && t.strikeIntervalLongMs == 1100 && t.compressFromRunes == 4 && t.bindAfterLastStrikeMs == 1800 &&
				t.revealAfterBindMs == 900 && t.beatAckTimeoutMs == 700 && t.beatAckWaitCapMs == 2600 && t.resultHoldMs == 0,
			"timing v3 constants (alpha/rc/r87421/B6-optics/timing-table.json; resultHoldMs 0 = held, I5 decision 3; R8.7.4.22 wait cap 2600)");
		const Timing v2{};
		Check(v2.beatAckTimeoutMs == 0 && v2.strikeIntervalLongMs == 0, "the default (vector) timing stays ungated v2");
		// a prompt host: LANDED 1300 ms after each strike, SEAL|DONE 800 ms after the BIND -> the authored schedule exactly
		const auto prompt = RunPerformance(3, t, 1300, 800);
		Check(prompt.strikes == std::vector<std::int64_t>{ 600, 2100, 3600 }, "prompt host: strikes at 600 / 2100 / 3600");
		Check(prompt.bind == 5400 && prompt.result == 6300, "prompt host: BIND at 5400, reveal at 6300");
		// a slow host: LANDED 1800 ms after each strike (300 ms late) -> each next beat waits for it (fires on the native tick after it,
		// 10 ms here), never before it, and the rest of the schedule shifts with it
		const auto slow = RunPerformance(3, t, 1800, 800);
		Check(slow.strikes == std::vector<std::int64_t>{ 600, 2410, 4220 }, "slow host: each strike waits for the previous LANDED");
		Check(slow.bind == 6030 && slow.result == 6930, "slow host: BIND after the last LANDED");
		// a silent host: no LANDED, no SEAL -> the first gate opens at schedule + the 2600 cap, every later one (the host has lapsed) at
		// schedule + 700; the performance ends (never blocks)
		const auto silent = RunPerformance(3, t, -1, -1);
		Check(silent.strikes == std::vector<std::int64_t>{ 600, 4700, 6900 }, "silent host: strike 2 at schedule + 2600 (cap), strike 3 at schedule + 700");
		Check(silent.bind == 9400 && silent.result == 11000, "silent host: BIND and reveal at schedule + 700; RESULT_SUCCESS is reached");
		for (std::int64_t n = 1; n <= 6; ++n) {
			const auto bound = 600 + (n - 1) * (n >= 4 ? 1100 : 1500) + 1800 + 900 + 2600 + n * 700;
			const auto r = RunPerformance(n, t, -1, -1);
			Check(r.result > 0 && r.result <= bound + 10 && static_cast<std::int64_t>(r.strikes.size()) == n, "silent host never blocks the result (n = " + std::to_string(n) + ")");
		}
		// four or more runes use the compressed interval
		const auto four = RunPerformance(4, t, 900, 500);
		Check(four.strikes == std::vector<std::int64_t>{ 600, 1700, 2800, 3900 }, "4 runes: 1100 ms interval");
		// acks that do not belong to the performance never open a gate
		const auto stale = RunPerformance(2, t, 100, 100, 30000, 777);
		Check(stale.strikes == std::vector<std::int64_t>{ 600, 4700 } && stale.result == 4700 + 1800 + 700 + 900 + 700, "a stale-token LANDED / SEAL is ignored");
		const auto early = RunPerformance(2, t, 100, -1, 30000, 0, 1);   // LANDED k+1 for strike k: a strike not yet sent
		Check(early.strikes == std::vector<std::int64_t>{ 600, 4700 }, "a LANDED for a strike not yet sent is ignored");
		// SEAL|DONE before the BIND is ignored
		{
			auto s = ToPerforming(1, t);
			Effects fx;
			Step(s, { EventKind::kAckSeal, static_cast<std::int64_t>(s.token), 0, {} }, fx, t);
			Check(!s.sealed, "SEAL|DONE before the BIND is dropped");
		}
		// Accept / Back still skips at once, whatever the gates are waiting for
		{
			auto s = ToPerforming(3, t);
			Effects fx;
			Step(s, { EventKind::kTick, 600, 0, {} }, fx, t);
			fx.clear();
			Step(s, { EventKind::kAccept, 1, 0, {} }, fx, t);
			Check(s.state == State::kResultSuccess && !fx.empty() && Format(fx[0]) == "Beat:" + std::to_string(s.token) + ":SKIP", "Accept skips at once while a gate waits");
		}
		// the ungated (v2) schedule ignores presentation acks entirely
		const auto v2a = RunPerformance(3, v2, 100, 100);
		const auto v2b = RunPerformance(3, v2, -1, -1);
		Check(v2a.strikes == v2b.strikes && v2a.result == v2b.result && v2a.strikes == std::vector<std::int64_t>{ 600, 1150, 1700 }, "v2 timing is unchanged by acks");
	}

	// R8.7.4.21 I5 decision 3: RESULT_SUCCESS is held (the spent rune row stays) until Accept / Back or an interrupt; never a timed exit.
	WS::StatePolicy::Session ToResult(const WS::StatePolicy::Timing& a_t)
	{
		using namespace WS::StatePolicy;
		auto s = ToPerforming(3, a_t);
		Effects fx;
		Step(s, { EventKind::kAccept, 1, 0, {} }, fx, a_t);   // skip to the result (the same RESULT_SUCCESS the performance reaches)
		return s;
	}
	bool HasEnd(const WS::StatePolicy::Effects& a_fx)
	{
		for (const auto& e : a_fx)
			if (e.kind == WS::StatePolicy::EffectKind::kEnd) return true;
		return false;
	}
	void ResultHoldChecks()
	{
		using namespace WS::StatePolicy;
		const auto& t = kPerformanceV3;
		{
			auto s = ToResult(t);
			Check(s.state == State::kResultSuccess, "held result: RESULT_SUCCESS reached");
			Effects fx;
			for (int i = 0; i < 60000; ++i) Step(s, { EventKind::kTick, 10, 0, {} }, fx, t);   // 600 s of native ticks
			Check(s.state == State::kResultSuccess && !HasEnd(fx) && s.token != 0u, "held result: 600 s of ticks never end the session (no timed exit)");
			fx.clear();
			Step(s, { EventKind::kAccept, 1, 0, {} }, fx, t);
			Check(s.state == State::kExiting && s.reason == ExitReason::kDone && HasEnd(fx), "held result: Accept (Continue) ends the session (End clears the row)");
		}
		{
			auto s = ToResult(t);
			Effects fx;
			Step(s, { EventKind::kTick, 5000, 0, {} }, fx, t);
			fx.clear();
			Step(s, { EventKind::kBack, 0, 0, {} }, fx, t);
			Check(s.state == State::kExiting && s.reason == ExitReason::kDone && HasEnd(fx), "held result: Back (dismiss) ends the session");
		}
		for (const auto cause : { Cause::kHit, Cause::kCombat, Cause::kDeath, Cause::kCell, Cause::kForced, Cause::kF10, Cause::kEmergency, Cause::kRace, Cause::kPreload, Cause::kStanceLost }) {
			auto s = ToResult(t);
			Effects fx;
			Step(s, { EventKind::kTick, 90000, 0, {} }, fx, t);
			fx.clear();
			Step(s, { EventKind::kInterrupt, 0, 0, cause }, fx, t);
			Check(s.state == State::kExiting && s.reason == ExitReason::kAbort && HasEnd(fx), std::string("held result: an interrupt ends the session (cause ") + std::string(Name(cause)) + ")");
		}
		{
			auto s = ToResult(t);
			Effects fx;
			Step(s, { EventKind::kTick, 90000, 0, {} }, fx, t);
			fx.clear();
			Step(s, { EventKind::kPostLoad, 0, 0, {} }, fx, t);
			Check(s.state == State::kIdle && !fx.empty() && fx[0].kind == EffectKind::kReset, "held result: a load resets the host (Reset clears the row)");
		}
		{
			// negative control: the pre-I5 timing (resultHoldMs 1200, also the vector default) still ends the session 1.2 s after the result
			Timing timed = t;
			timed.resultHoldMs = 1200;
			auto s = ToResult(timed);
			Effects fx;
			std::int64_t at = -1;
			for (int i = 1; i <= 300 && at < 0; ++i) {
				Step(s, { EventKind::kTick, 10, 0, {} }, fx, timed);
				if (s.state == State::kExiting) at = 10 * i;
			}
			Check(at == 1200 && HasEnd(fx), "control: a timed result hold (1200) ends the session at 1200 ms");
		}
	}

	// The R8.7.4.21 presentation acks on the wire.
	void PresentationAckChecks()
	{
		using namespace WS::ProtocolPolicy;
		const auto landed = ParseAck("12|BEAT|3|LANDED", 12.0f);
		Check(landed.kind == AckKind::kBeatLanded && landed.seq == 3 && landed.token == 12u, "BEAT|k|LANDED");
		const auto fail = ParseAck("12|BEAT|5|FAIL|NO_RUNE", 12.0f);
		Check(fail.kind == AckKind::kBeatFail && fail.seq == 5 && fail.code == "NO_RUNE", "BEAT|k|FAIL|code");
		const auto seal = ParseAck("12|SEAL|DONE", 12.0f);
		Check(seal.kind == AckKind::kSealDone && seal.token == 12u, "SEAL|DONE");
		Check(ParseAck("12|Beat|1|Landed", 12.0f).kind == AckKind::kBeatLanded, "verbs are case-insensitive");
		for (const char* bad : { "12|BEAT|0|LANDED", "12|BEAT|7|LANDED", "12|BEAT|1|LANDED|x", "12|BEAT|1|FAIL", "12|BEAT|1|FAIL|bad code", "12|BEAT|x|LANDED",
				 "12|SEAL", "12|SEAL|DONE|1", "12|SEAL|OPEN" }) {
			Check(ParseAck(bad, 12.0f).kind == AckKind::kInvalid, std::string("malformed presentation ack rejected: ") + bad);
		}
		Check(ParseAck("12|BEAT|1|LANDED", 13.0f).kind == AckKind::kInvalid, "numArg must equal the token");
		Check(ParseAck("12|CLEARED|4", 12.0f).kind == AckKind::kCleared && ParseAck("12|CLEARED|4|OPTICS_OFF", 12.0f).kind == AckKind::kInvalid,
			"CLEARED keeps its v3 shape");
	}

