		Check(Map(State::kSelectFormula, Button::kCancel, Phase::kDown, 0.0f, tracker).command == Command::kBack, "Back from formulas");
		Check(Map(State::kSelectFormula, Button::kOps, Phase::kDown, 0.0f, tracker).command == Command::kOps, "X opens the operations page");
		Check(Map(State::kOperations, Button::kOps, Phase::kDown, 0.0f, tracker).command == Command::kBack, "X closes the operations page");
		Check(Map(State::kSelectItem, Button::kOps, Phase::kDown, 0.0f, tracker).command == Command::kNone, "X needs a selected item");
