		Check(Map(State::kConfirm, Button::kAccept, Phase::kHeld, 0.5f, tracker).command == Command::kNone, "Accept held is the hold, not a repeat");
		Check(Map(State::kConfirm, Button::kAccept, Phase::kUp, 0.6f, tracker).command == Command::kHoldEnd, "Accept up ends the hold");
		Check(Map(State::kPerforming, Button::kAccept, Phase::kDown, 0.0f, tracker).command == Command::kSkip, "Accept skips the performance");
		Check(Map(State::kPerforming, Button::kCancel, Phase::kDown, 0.0f, tracker).command == Command::kSkip, "Back skips the performance");
		Check(Map(State::kPerforming, Button::kDown, Phase::kDown, 0.0f, tracker).command == Command::kNone, "no navigation while performing");
