		Check(Map(State::kSelectItem, Button::kViewBack, Phase::kHeld, 1.9f, tracker).command == Command::kNone, "View held under 2 s");
		Check(Map(State::kSelectItem, Button::kViewBack, Phase::kHeld, 2.0f, tracker).command == Command::kEmergency, "View held 2 s is the emergency close");
		Check(Map(State::kSelectItem, Button::kViewBack, Phase::kHeld, 2.5f, tracker).command == Command::kNone, "emergency fires once");
